import { frame, createState } from './neon.js';

test('frame: bounce off left side of brick', () => {
  const state = createState(1);
  const ball = { x: 100, y: 100, r: 7, vx: 100, vy: 0 };
  const brick = { x: 105, y: 90, w: 20, h: 20, alive: true };
  state.ball = ball;
  state.bricks = [brick];

  // Mock canvas context
  const ctx = {
    fillRect: () => {},
    arc: () => {},
    fill: () => {},
    beginPath: () => {},
    fillText: () => { },
  };

  frame(ctx, state);

  assert.equal(brick.alive, false, 'Brick should be broken');
